function isClosed(status: Issue["status"]): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

function indexById(all: readonly Issue[]): Map<IssueId, Issue> {
  return new Map(all.map((i) => [i.id, i]));
}

/** Level of an issue: a root is 0. Guards against corrupt loops. */
function levelOf(byId: Map<IssueId, Issue>, issue: Issue): number {
  let level = 0;
  const seen = new Set<IssueId>([issue.id]);
  let current = issue;
  while (current.parentId !== null) {
    const next = byId.get(current.parentId);
    if (!next || seen.has(next.id)) break;
    seen.add(next.id);
    level += 1;
    current = next;
  }
  return level;
}

/** Every issue below `rootId` at any depth, archived ones included. */
function descendantsOf(all: readonly Issue[], rootId: IssueId): Issue[] {
  const children = new Map<IssueId, Issue[]>();
  for (const i of all) {
    if (i.parentId === null) continue;
    const list = children.get(i.parentId) ?? [];
    list.push(i);
    children.set(i.parentId, list);
  }
  const out: Issue[] = [];
  const seen = new Set<IssueId>([rootId]);
  const queue: IssueId[] = [rootId];
  while (queue.length > 0) {
    for (const child of children.get(queue.shift() as IssueId) ?? []) {
      if (seen.has(child.id)) continue;
      seen.add(child.id);
      out.push(child);
      queue.push(child.id);
    }
  }
  return out;
}

/** Height of the subtree below `rootId`: 0 for a leaf. */
function heightOf(all: readonly Issue[], rootId: IssueId): number {
  const byId = indexById(all);
  let max = 0;
  const root = byId.get(rootId);
  if (!root) return 0;
  const base = levelOf(byId, root);
  for (const d of descendantsOf(all, rootId)) {
    max = Math.max(max, levelOf(byId, d) - base);
  }
  return max;
}

/** Tells the parent's assignee once its last open sub-issue has closed. */
async function notifyIfCompleted(actor: Actor, child: Issue): Promise<void> {
  if (child.parentId === null) return;
  const all = await issueRepo.listAllProjectIssues(child.orgId, child.projectId);
  const parent = indexById(all).get(child.parentId);
  if (!parent || isArchived(parent) || parent.assigneeId === null) return;
  const live = descendantsOf(all, parent.id).filter((i) => !isArchived(i));
  if (live.some((i) => !isClosed(i.status))) return;
  await notify(child.orgId, "sub_issues_completed", [parent.assigneeId], {
    title: "All sub-issues completed",
    body: `Every sub-issue of issue ${parent.id} is closed`,
    href: `/issues/${parent.id}`,
    actorId: actor.userId,
  });
}

export async function setIssueParent(
  actor: Actor,
  input: SetIssueParentInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const all = await issueRepo.listAllProjectIssues(input.orgId, issue.projectId);
  const byId = indexById(all);

  if (input.parentId !== null) {
    const parent = byId.get(input.parentId);
    if (!parent) throw new NotFoundError("Issue", input.parentId);
    assertNotArchived("Issue", parent.id, parent);
    if (
      parent.id === issue.id ||
      descendantsOf(all, issue.id).some((d) => d.id === parent.id)
    ) {
      throw new IssueHierarchyError(issue.id, "cycle");
    }
    if (
      levelOf(byId, parent) + 1 + heightOf(all, issue.id) >
      MAX_SUB_ISSUE_DEPTH
    ) {
      throw new IssueHierarchyError(issue.id, "too_deep");
    }
  }

  if (issue.parentId === input.parentId) return issue;

  const after = await issueRepo.setIssueParent(
    input.orgId,
    input.issueId,
    input.parentId,
  );

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: ["parentId"],
  });

  return after;
}

